export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-resource-guard-v1","checksum":"d7e02c5a5d9b523b08513f4ed65988281ef17dfeceb0da0541109e686cfa41d6","manifestSha256":"9583b3a4f3c541241c8ddf33e064a67263b21173743b92e50be1d6e5179e8e19","sql":"-- Core schema version identity-resource-guard-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/identity_task_access.sql\n\n-- Temporary installer lookup for the table owner; revoked after the attachments.\nGRANT USAGE ON SCHEMA gov TO backbone_owner;\n-- Restrictive project checks retain legacy crossings and the run-secret accounting exception.\nCREATE OR REPLACE FUNCTION gov.identity_task_access(p_task uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE project uuid; viewer uuid; principal uuid;\nBEGIN\n  principal:=sec.current_principal();\n  IF principal=sec.system_principal() THEN RETURN true; END IF;\n  IF p_task IS NULL OR principal IS NULL THEN RETURN false; END IF;\n  SELECT project_id INTO project FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND task_id=p_task;\n  IF NOT FOUND THEN RETURN false; END IF;\n  viewer:=sec.viewer();\n  RETURN gov.identity_person_task_access(p_task,viewer,p_write);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_task_access(uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_task_access(uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_person_task_access.sql\n\n-- Current project access is separate from immutable records of everyone who saw its words.\nCREATE OR REPLACE FUNCTION gov.identity_person_task_access(p_task uuid,p_person uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE project uuid; permission text; role text;\nBEGIN\n  SELECT project_id INTO project FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND task_id=p_task;\n  IF NOT FOUND THEN RETURN false; END IF;\n  role:=sec.role_of(p_person);\n  IF role IS NULL THEN RETURN false; END IF;\n  SELECT CASE WHEN p.owner_id=p_person THEN 'owner' ELSE a.access END INTO permission\n  FROM app.identity_projects p LEFT JOIN app.identity_project_people a ON a.workspace_id=p.workspace_id AND a.project_id=p.project_id AND a.person_id=p_person\n  WHERE p.workspace_id=sec.current_workspace() AND p.project_id=project;\n  IF permission IS NULL AND EXISTS(SELECT FROM app.identity_workspace_projects WHERE workspace_id=sec.current_workspace() AND project_id=project) THEN permission:='editor'; END IF;\n  RETURN coalesce((permission IN ('owner','editor') AND role<>'guest') OR (NOT p_write AND permission IS NOT NULL),false);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_person_task_access(uuid,uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_person_task_access(uuid,uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_bind_new_task.sql\n\n-- Every task entry point receives a private project before subsequent writes.\n-- A project-aware creator may replace this default binding in the same transaction.\nCREATE FUNCTION gov.identity_bind_new_task() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nBEGIN\n  INSERT INTO app.identity_projects(workspace_id,project_id,owner_id) VALUES(NEW.workspace_id,NEW.id,NEW.requested_by);\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(NEW.workspace_id,NEW.id,NEW.id);\n  INSERT INTO app.identity_project_people(workspace_id,project_id,person_id,access)\n  SELECT NEW.workspace_id,NEW.id,p.id,CASE WHEN p.role='guest' THEN 'viewer' ELSE 'editor' END\n  FROM app.principals p WHERE p.workspace_id=NEW.workspace_id AND p.kind='person' AND p.status='active' AND p.id<>NEW.requested_by\n    AND (p.id=NEW.on_behalf_of OR NEW.visibility='workspace');\n  IF NEW.visibility='workspace' THEN INSERT INTO app.identity_workspace_projects(workspace_id,project_id) VALUES(NEW.workspace_id,NEW.id); END IF;\n  RETURN NEW;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_bind_new_task() FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_bind_new_task() TO backbone_owner;\n\n-- gov/identity_run_lookup.sql\n\n-- Validate the one claimed row without reading app.runs and recursing through RLS.\n-- This permits native claim/holder accounting, not a run-name-only read bypass.\nCREATE FUNCTION gov.identity_run_lookup(p_run uuid,p_fence bigint) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n  SELECT p_run=nullif(current_setting('backbone.run',true),'')::uuid AND EXISTS(\n    SELECT FROM ops.run_secrets s WHERE s.workspace_id=sec.current_workspace() AND s.run_id=p_run AND s.fence=p_fence\n      AND s.secret_hash=encode(sha256(convert_to(coalesce(current_setting('backbone.secret',true),''),'UTF8')),'hex'))\n$$;\nREVOKE ALL ON FUNCTION gov.identity_run_lookup(uuid,bigint) FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_run_lookup(uuid,bigint) TO backbone_owner;\n\n-- gov/identity_effect_decider_access.sql\n\n-- A decision is an explicit capability for its exact proposal. An admin role is not.\nCREATE FUNCTION gov.identity_effect_decider_access(p_decision uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n  SELECT NOT sec.names_run() AND sec.current_principal() IS NOT NULL AND EXISTS(\n    SELECT FROM app.decisions d WHERE d.workspace_id=sec.current_workspace() AND d.id=p_decision\n      AND (d.checker_id=sec.viewer() OR (d.checker_kind='verifier' AND sec.is_verifier(sec.current_principal()))))\n$$;\nREVOKE ALL ON FUNCTION gov.identity_effect_decider_access(uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_effect_decider_access(uuid) TO backbone_app,backbone_owner;\n\n-- gov/identity_run_decider_access.sql\n\n-- Effects are already restricted to a live grant or the exact decision capability.\n-- This reveals only a run associated with a question the caller may decide.\nCREATE FUNCTION gov.identity_run_decider_access(p_run uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n  SELECT NOT sec.names_run() AND sec.current_principal() IS NOT NULL AND EXISTS(\n    SELECT FROM app.effects e WHERE e.workspace_id=sec.current_workspace() AND e.run_id=p_run\n      AND gov.identity_effect_decider_access(e.decision_id))\n$$;\nREVOKE ALL ON FUNCTION gov.identity_run_decider_access(uuid) FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_run_decider_access(uuid) TO backbone_owner;\n\n-- gov/identity_cancel_mandate_work.sql\n\n-- A private cancellation service acts only on already-revoked mandates whose\n-- revocation the caller could authorize. It never returns runs or effect bodies.\nCREATE FUNCTION gov.identity_cancel_mandate_work(p_mandates uuid[],p_actor uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE r record; old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\nBEGIN\n  IF p_actor IS NULL OR sec.current_principal() IS DISTINCT FROM p_actor OR p_mandates IS NULL\n    OR EXISTS(SELECT FROM unnest(p_mandates) x(id) LEFT JOIN app.mandates m ON m.workspace_id=sec.current_workspace() AND m.id=x.id\n      WHERE m.id IS NULL OR m.revoked_at IS NULL OR NOT(p_actor IN(m.issuer_id,m.on_behalf_of_id) OR (NOT sec.names_run() AND sec.is_admin(p_actor))))\n    THEN RAISE EXCEPTION 'denied: cancellation requires an authorized revoked mandate'; END IF;\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true);\n  PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  FOR r IN SELECT id FROM app.runs WHERE workspace_id=sec.current_workspace() AND mandate_id=ANY(p_mandates) AND status IN('queued','running','waiting') LOOP\n    PERFORM gov._stop_run(r.id,'cancelled','mandate revoked');\n  END LOOP;\n  FOR r IN SELECT id FROM app.effects WHERE workspace_id=sec.current_workspace() AND mandate_id=ANY(p_mandates) AND status IN('proposed','awaiting_checker','allowed','claimed') LOOP\n    PERFORM gov._cancel_effect(r.id,'mandate revoked');\n  END LOOP;\n  PERFORM gov._append('identity.mandate_work_cancelled',p_actor::text,jsonb_build_object('mandates',p_mandates),p_actor);\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_cancel_mandate_work(uuid[],uuid) FROM PUBLIC,backbone_app,backbone_operator;\n\n-- gov/claim_run.sql\n\n-- A worker process claims a run by its id. Only a worker claims: a session naming a principal or a\n-- run is refused. Returns its fence and secret, or no row when its mandate no longer stands (the\n-- run is then stopped). The worker states what it runs: 'piece' with the registered piece, or\n-- 'direct'. A run is claimed only for exactly what carries it, so a piece never executes a direct\n-- run or another piece's (or version's), and a direct worker never executes a piece's.\nCREATE OR REPLACE FUNCTION gov.claim_run(p_run uuid, p_worker text, p_lease_ms integer, p_carrier text, p_piece uuid DEFAULT NULL) RETURNS TABLE (fence bigint, secret text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  c record;\n  bound record;\nBEGIN\n  IF sec.current_workspace() IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session names no workspace';\n  END IF;\n  IF nullif(current_setting('backbone.principal', true), '') IS NOT NULL OR sec.names_run() THEN\n    RAISE EXCEPTION 'workers_only: runs are claimed by worker processes, not by principals or runs';\n  END IF;\n  IF p_carrier IS NULL OR NOT ((p_carrier = 'piece' AND p_piece IS NOT NULL) OR (p_carrier = 'direct' AND p_piece IS NULL)) THEN\n    RAISE EXCEPTION 'invalid: a worker states what it runs: ''piece'' with a registered piece, or ''direct''';\n  END IF;\n  PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  -- Revocation takes workspace then run; claims must take the same order.\n  PERFORM gov._lock_workspace();\n  SELECT carrier, piece_id INTO bound FROM app.runs WHERE workspace_id = sec.current_workspace() AND id = p_run FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'not_found: no such run in this workspace';\n  END IF;\n  IF (bound.carrier, bound.piece_id) IS DISTINCT FROM (p_carrier, p_piece) THEN\n    RAISE EXCEPTION 'other_piece: the run is carried by something other than what this worker runs';\n  END IF;\n  IF NOT gov._claimable(p_run, false) THEN\n    RAISE EXCEPTION 'not_claimable: the run is held, finished or stopped';\n  END IF;\n  SELECT * INTO c FROM gov._claim(p_run, p_worker, p_lease_ms);\n  PERFORM set_config('backbone.principal','',true);\n  IF c.fence IS NOT NULL THEN\n    RETURN QUERY SELECT c.fence, c.secret;\n  END IF;\nEND\n$$;\n\n-- gov/claim_next_run.sql\n\n-- A worker takes the next claimable run of any workspace, from an empty session, and leaves the\n-- session empty again. Runs whose mandate no longer stands are stopped on the way, not handed out.\n-- Only runs carried by exactly what the worker runs ('piece' with p_piece, or 'direct') are handed to it.\nCREATE OR REPLACE FUNCTION gov.claim_next_run(p_worker text, p_lease_ms integer, p_carrier text, p_piece uuid DEFAULT NULL)\nRETURNS TABLE (workspace_id uuid, run_id uuid, fence bigint, secret text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  q record;\n  r record;\n  c record;\n  busy_workspaces uuid[] := '{}';\n  wanted text := CASE WHEN p_carrier = 'piece' AND p_piece IS NOT NULL THEN p_piece::text WHEN p_carrier = 'direct' AND p_piece IS NULL THEN 'direct' END;\nBEGIN\n  IF NOT sec.session_is_empty() THEN\n    RAISE EXCEPTION 'empty_session_only: the queue is read from a session that names nobody';\n  END IF;\n  IF wanted IS NULL THEN\n    RAISE EXCEPTION 'invalid: a worker states what it runs: ''piece'' with a registered piece, or ''direct''';\n  END IF;\n  LOOP\n    -- Select without a queue/run lock, bind its workspace for RLS, then lock workspace first.\n    SELECT x.* INTO q FROM ops.run_queue x\n    WHERE x.carrier_key = wanted AND x.claimable_after <= clock_timestamp()\n      AND NOT (x.workspace_id = ANY(busy_workspaces))\n    ORDER BY x.claimable_after, x.enqueued_at LIMIT 1;\n    EXIT WHEN NOT FOUND;\n    PERFORM set_config('backbone.workspace', q.workspace_id::text, true);\n    PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n    PERFORM 1 FROM app.ledger_heads WHERE workspace_id = q.workspace_id FOR UPDATE SKIP LOCKED;\n    IF NOT FOUND THEN\n      busy_workspaces := array_append(busy_workspaces, q.workspace_id);\n      PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n      CONTINUE;\n    END IF;\n    SELECT * INTO r FROM app.runs x WHERE x.workspace_id = q.workspace_id AND x.id = q.run_id FOR UPDATE SKIP LOCKED;\n    IF NOT FOUND THEN\n      UPDATE ops.run_queue SET claimable_after = clock_timestamp() + interval '1 second' WHERE ops.run_queue.run_id = q.run_id;\n    ELSIF r.status NOT IN ('queued', 'running', 'waiting') THEN\n      DELETE FROM ops.run_queue WHERE ops.run_queue.run_id = q.run_id;\n    ELSIF r.status = 'waiting' AND NOT r.woken THEN\n      UPDATE ops.run_queue SET claimable_after = NULL WHERE ops.run_queue.run_id = q.run_id;\n    ELSIF r.status = 'running' AND r.lease_expires_at > clock_timestamp() THEN\n      UPDATE ops.run_queue SET claimable_after = r.lease_expires_at WHERE ops.run_queue.run_id = q.run_id;\n    ELSE\n      SELECT * INTO c FROM gov._claim(q.run_id, p_worker, p_lease_ms);\n      IF c.fence IS NOT NULL THEN\n        PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n        RETURN QUERY SELECT q.workspace_id, q.run_id, c.fence, c.secret;\n        RETURN;\n      END IF;\n    END IF;\n    PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n  END LOOP;\n  PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\nEND\n$$;\n\n-- gov/claim_next_effect.sql\n\n-- A dispatcher takes the next due effect of any workspace, from an empty session, as that\n-- workspace's system principal, and leaves the session empty. A dispatching effect whose\n-- dispatcher went silent comes back as stale, with its claim, once its lease and the grace window\n-- (30 seconds; effect-gateway contract, stale dispatch) have passed: to be inspected and observed, never sent again.\nCREATE OR REPLACE FUNCTION gov.claim_next_effect(p_worker text, p_lease_ms integer)\nRETURNS TABLE (workspace_id uuid, effect_id uuid, claim_token text, stale boolean, system_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  grace constant interval := interval '30 seconds';\n  q record;\n  e record;\n  v_claim text;\n  v_system uuid;\nBEGIN\n  IF NOT sec.session_is_empty() THEN\n    RAISE EXCEPTION 'empty_session_only: the queue is read from a session that names nobody';\n  END IF;\n  IF p_lease_ms IS NULL OR p_lease_ms <= 0 THEN\n    RAISE EXCEPTION 'invalid: a lease is a positive number of milliseconds';\n  END IF;\n  LOOP\n    SELECT * INTO q FROM ops.effect_queue x WHERE x.due_at <= clock_timestamp()\n    ORDER BY x.due_at, x.enqueued_at LIMIT 1 FOR UPDATE SKIP LOCKED;\n    EXIT WHEN NOT FOUND;\n    PERFORM set_config('backbone.workspace', q.workspace_id::text, true);\n    PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n    v_system := sec.system_principal();\n    SELECT * INTO e FROM app.effects x WHERE x.workspace_id = q.workspace_id AND x.id = q.effect_id FOR UPDATE SKIP LOCKED;\n    IF NOT FOUND THEN\n      UPDATE ops.effect_queue x SET due_at = clock_timestamp() + interval '1 second' WHERE x.effect_id = q.effect_id;\n    ELSIF (e.status = 'allowed' AND (e.not_before IS NULL OR e.not_before <= clock_timestamp()))\n          OR (e.status = 'claimed' AND q.lease_expires_at <= clock_timestamp()) THEN\n      v_claim := gov._claim_effect(e.id, p_lease_ms);\n      PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n      RETURN QUERY SELECT q.workspace_id, e.id, v_claim, false, v_system;\n      RETURN;\n    ELSIF e.status = 'allowed' THEN\n      UPDATE ops.effect_queue x SET due_at = e.not_before WHERE x.effect_id = q.effect_id;\n    ELSIF e.status = 'claimed' THEN\n      UPDATE ops.effect_queue x SET due_at = q.lease_expires_at WHERE x.effect_id = q.effect_id;\n    ELSIF e.status = 'dispatching' AND q.lease_expires_at + grace <= clock_timestamp()\n          AND (q.stale_handed_until IS NULL OR q.stale_handed_until <= clock_timestamp()) THEN\n      UPDATE ops.effect_queue x SET stale_handed_until = clock_timestamp() + make_interval(secs => p_lease_ms / 1000.0),\n                                    due_at = clock_timestamp() + make_interval(secs => p_lease_ms / 1000.0)\n      WHERE x.effect_id = q.effect_id;\n      PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n      RETURN QUERY SELECT q.workspace_id, e.id, q.claim_token, true, v_system;\n      RETURN;\n    ELSIF e.status = 'dispatching' THEN\n      UPDATE ops.effect_queue x SET due_at = greatest(q.lease_expires_at + grace, coalesce(q.stale_handed_until, q.lease_expires_at + grace))\n      WHERE x.effect_id = q.effect_id;\n    ELSE\n      DELETE FROM ops.effect_queue x WHERE x.effect_id = q.effect_id;\n    END IF;\n    PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n  END LOOP;\n  PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\nEND\n$$;\n\n-- gov/claim_next_verification.sql\n\n-- A verifier worker takes the next question of any workspace's verification queue, from an empty\n-- session, under a short lease, and leaves the session empty. Escalated, answered or withdrawn\n-- questions leave the queue on the way.\nCREATE OR REPLACE FUNCTION gov.claim_next_verification(p_worker text, p_lease_ms integer)\nRETURNS TABLE (workspace_id uuid, decision_id uuid, verifier_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  q record;\n  d record;\n  paused boolean;\n  held uuid[] := ARRAY[]::uuid[];\nBEGIN\n  IF NOT sec.session_is_empty() THEN\n    RAISE EXCEPTION 'empty_session_only: the queue is read from a session that names nobody';\n  END IF;\n  IF p_lease_ms IS NULL OR p_lease_ms <= 0 THEN\n    RAISE EXCEPTION 'invalid: a lease is a positive number of milliseconds';\n  END IF;\n  LOOP\n    SELECT * INTO q FROM ops.verification_queue x WHERE x.available_at <= clock_timestamp() AND NOT (x.decision_id = ANY(held))\n    ORDER BY x.enqueued_at LIMIT 1 FOR UPDATE SKIP LOCKED;\n    EXIT WHEN NOT FOUND;\n    PERFORM set_config('backbone.workspace', q.workspace_id::text, true);\n    PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n    SELECT * INTO d FROM app.decisions x WHERE x.workspace_id = q.workspace_id AND x.id = q.decision_id;\n    paused := d.subject_kind = 'promotion' AND NOT gov._promotion_sources_allowed(d.subject_id);\n    PERFORM set_config('backbone.principal','',true);\n    PERFORM set_config('backbone.workspace', '', true);\n    IF paused THEN\n      held := array_append(held, q.decision_id);\n      CONTINUE;\n    END IF;\n    IF d.id IS NULL OR d.status <> 'open' OR d.escalated_at IS NOT NULL THEN\n      DELETE FROM ops.verification_queue x WHERE x.decision_id = q.decision_id;\n    ELSE\n      UPDATE ops.verification_queue x SET available_at = clock_timestamp() + make_interval(secs => p_lease_ms / 1000.0), worker = p_worker\n      WHERE x.decision_id = q.decision_id;\n      RETURN QUERY SELECT q.workspace_id, q.decision_id, q.verifier_id;\n      RETURN;\n    END IF;\n  END LOOP;\nEND\n$$;\n\n-- gov/revoke_mandate.sql\n\n-- Revoke a mandate and its whole delegation tree in one operation (I-3). Its runs stop\n-- at once, effects not yet dispatched are cancelled and their questions withdrawn. Only its\n-- grantor, the person it acts for, or an owner or admin revokes it. Returns how many were revoked.\nCREATE OR REPLACE FUNCTION gov.revoke_mandate(p_mandate uuid) RETURNS integer\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  me uuid := sec.current_principal();\n  m record;\n  revoked uuid[];\n  r record;\n  e record;\nBEGIN\n  IF me IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session acts as nobody';\n  END IF;\n  SELECT * INTO m FROM app.mandates WHERE workspace_id = ws AND id = p_mandate;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'not_found: no such mandate in this workspace';\n  END IF;\n  IF me NOT IN (m.issuer_id, m.on_behalf_of_id) AND NOT (NOT sec.names_run() AND sec.is_admin(me)) THEN\n    RAISE EXCEPTION 'role: only the grantor, the person it acts for, or an admin revokes a mandate';\n  END IF;\n  PERFORM gov._lock_workspace();\n  SELECT array_agg(id) INTO revoked FROM app.mandates\n  WHERE workspace_id = ws AND id IN (SELECT gov._subtree(p_mandate)) AND revoked_at IS NULL;\n  IF revoked IS NULL THEN\n    RETURN 0;\n  END IF;\n  UPDATE app.mandates SET revoked_at = clock_timestamp(), revoked_by = me WHERE workspace_id = ws AND id = ANY (revoked);\n  PERFORM gov.identity_cancel_mandate_work(revoked,me);\n  FOR r IN SELECT unnest(revoked) AS id LOOP\n    PERFORM gov._append('mandate.revoked', r.id::text, jsonb_build_object('root', p_mandate));\n  END LOOP;\n  RETURN cardinality(revoked);\nEND\n$$;\n\nSET ROLE backbone_owner;\n\n-- app/identity_directory_deleted.sql\n\n-- Deletion hides the SCIM resource without releasing its immutable account binding.\nCREATE TABLE app.identity_directory_deleted(workspace_id uuid NOT NULL,principal_id uuid NOT NULL,PRIMARY KEY(workspace_id,principal_id),FOREIGN KEY(workspace_id,principal_id) REFERENCES app.identity_directory(workspace_id,principal_id));\nALTER TABLE app.identity_directory_deleted ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_directory_deleted FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_directory_deleted AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_directory_deleted FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_directory_deleted FROM PUBLIC,backbone_app,backbone_operator;\nGRANT SELECT,INSERT ON app.identity_directory_deleted TO backbone_gov;\n\n-- app/identity_workspace_projects.sql\n\n-- A legacy task explicitly published to the workspace keeps that audience for future people.\nCREATE TABLE app.identity_workspace_projects(workspace_id uuid NOT NULL,project_id uuid NOT NULL,PRIMARY KEY(workspace_id,project_id),FOREIGN KEY(workspace_id,project_id) REFERENCES app.identity_projects(workspace_id,project_id));\nALTER TABLE app.identity_workspace_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_workspace_projects FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_workspace_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_workspace_projects FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_workspace_projects FROM PUBLIC,backbone_app,backbone_operator;\nGRANT SELECT,INSERT,DELETE ON app.identity_workspace_projects TO backbone_gov;\n\n-- app/identity_resource_policies.sql\n\n-- The synchronous task trigger installs the binding after this validated insertion.\nDROP POLICY identity_project_insert ON app.tasks;\nCREATE POLICY identity_project_insert ON app.tasks AS RESTRICTIVE FOR INSERT TO backbone_gov\n  WITH CHECK(sec.current_principal()=sec.system_principal() OR (requested_by=sec.current_principal() AND sec.role_of(requested_by) IN('owner','admin','member')));\nCREATE TRIGGER identity_task_project_binding AFTER INSERT ON app.tasks FOR EACH ROW EXECUTE FUNCTION gov.identity_bind_new_task();\n-- Run-name lookup is required for validating its secret without recursive RLS.\n-- An admin role alone confers no read of a project's run or effect payload.\nDROP POLICY identity_project_crossing_read ON app.runs;\nCREATE POLICY identity_project_crossing_read ON app.runs AS RESTRICTIVE FOR SELECT TO backbone_gov\n  USING(CASE WHEN sec.names_run() THEN gov.identity_run_lookup(id,fence) ELSE gov.identity_task_access(task_id,false) OR gov.identity_run_decider_access(id) END);\nDROP POLICY identity_project_crossing_read ON app.effects;\nCREATE POLICY identity_project_crossing_read ON app.effects AS RESTRICTIVE FOR SELECT TO backbone_gov USING(gov.identity_task_access(task_id,false) OR gov.identity_effect_decider_access(decision_id));\n-- The assigned decider retains the native rule-of-two view and can settle that\n-- proposal through the existing guarded crossing. This is never a role-wide read.\nDROP POLICY identity_project_read ON app.effects;\nCREATE POLICY identity_project_read ON app.effects AS RESTRICTIVE FOR SELECT TO backbone_app\n  USING(gov.identity_task_access(task_id,false) OR gov.identity_effect_decider_access(decision_id));\nDROP POLICY identity_project_update ON app.effects;\nCREATE POLICY identity_project_update ON app.effects AS RESTRICTIVE FOR UPDATE TO backbone_gov USING(true)\n  WITH CHECK(gov.identity_task_access(task_id,true) OR gov.identity_effect_decider_access(decision_id) OR (status='cancelled' AND sec.is_admin(sec.current_principal())));\n\nSET ROLE backbone_gov;\n\n-- gov/identity_create_task.sql\n\n-- Restore the frozen schema authority after policy and trigger creation.\nREVOKE USAGE ON SCHEMA gov FROM backbone_owner;\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE OR REPLACE FUNCTION gov.identity_create_task(p_project uuid, p_title text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; task uuid;\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF gov.identity_project_access(p_project) NOT IN ('owner','editor') OR gov.identity_project_access(p_project) IS NULL THEN RAISE EXCEPTION 'denied: project is read only or unavailable'; END IF;\n  task:=gov.create_task(me,me,p_title,NULL,NULL);\n  UPDATE app.identity_task_projects SET project_id=p_project WHERE workspace_id=sec.current_workspace() AND task_id=task;\n  DELETE FROM app.identity_project_people WHERE workspace_id=sec.current_workspace() AND project_id=task AND task<>p_project;\n  DELETE FROM app.identity_workspace_projects WHERE workspace_id=sec.current_workspace() AND project_id=task AND task<>p_project;\n  DELETE FROM app.identity_projects WHERE workspace_id=sec.current_workspace() AND project_id=task AND task<>p_project;\n  INSERT INTO app.task_people(workspace_id,task_id,person_id)\n  SELECT sec.current_workspace(),task,p.owner_id FROM app.identity_projects p WHERE p.workspace_id=sec.current_workspace() AND p.project_id=p_project AND p.owner_id<>me\n  UNION SELECT sec.current_workspace(),task,a.person_id FROM app.identity_project_people a WHERE a.workspace_id=sec.current_workspace() AND a.project_id=p_project AND a.person_id<>me\n  ON CONFLICT(workspace_id,task_id,person_id) DO NOTHING;\n  RETURN task;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_create_task(uuid,text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_create_task(uuid,text) TO backbone_app;\n\n-- gov/identity_bind_task.sql\n\n-- Bind an existing private task only by its own requester in an owned project.\nCREATE OR REPLACE FUNCTION gov.identity_bind_task(p_project uuid,p_task uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid;\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF coalesce(gov.identity_project_access(p_project),'')<>'owner' OR NOT EXISTS(SELECT FROM app.tasks WHERE workspace_id=sec.current_workspace() AND id=p_task AND requested_by=me) THEN RAISE EXCEPTION 'denied: task binding belongs to its requester'; END IF;\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(sec.current_workspace(),p_task,p_project) ON CONFLICT(workspace_id,task_id) DO UPDATE SET project_id=EXCLUDED.project_id\n  WHERE app.identity_task_projects.project_id=p_task;\n  DELETE FROM app.identity_project_people WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  DELETE FROM app.identity_workspace_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  DELETE FROM app.identity_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  RETURN p_task;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_bind_task(uuid,uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_bind_task(uuid,uuid) TO backbone_app;\n\n-- gov/identity_project_access.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE OR REPLACE FUNCTION gov.identity_project_access(p_project uuid) RETURNS text\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid:=sec.current_principal(); access text;\nBEGIN\n  IF me IS NULL OR sec.principal_kind(me)<>'person' THEN RETURN NULL; END IF;\n  SELECT CASE WHEN p.owner_id=me THEN 'owner' ELSE a.access END INTO access\n  FROM app.identity_projects p LEFT JOIN app.identity_project_people a ON a.workspace_id=p.workspace_id AND a.project_id=p.project_id AND a.person_id=me\n  WHERE p.workspace_id=sec.current_workspace() AND p.project_id=p_project;\n  IF access IS NULL AND EXISTS(SELECT FROM app.identity_workspace_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_project) THEN access:='editor'; END IF;\n  IF sec.role_of(me)='guest' AND access IN ('owner','editor') THEN RETURN 'viewer'; END IF;\n  RETURN access;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_access(uuid) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_access(uuid) TO backbone_app;\n\n-- gov/join_channel_thread.sql\n\n-- Preserve the paired channel join as an explicit project grant. The service\n-- lookup is bounded to that paired account; no message content is returned.\nCREATE OR REPLACE FUNCTION gov.join_channel_thread(p_thread uuid,p_identity uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE ws uuid:=sec.current_workspace(); me uuid:=gov._person('not_by_runs'); old_person text:=coalesce(current_setting('backbone.principal',true),''); account uuid; task uuid; project uuid;\nBEGIN\n  SELECT account_id INTO account FROM app.channel_identities WHERE workspace_id=ws AND id=p_identity AND person_id=me;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no such paired identity'; END IF;\n  PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT task_id INTO task FROM app.channel_threads WHERE workspace_id=ws AND id=p_thread AND account_id=account;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no such thread for this paired identity'; END IF;\n  SELECT project_id INTO project FROM app.identity_task_projects WHERE workspace_id=ws AND task_id=task;\n  IF NOT FOUND THEN RAISE EXCEPTION 'denied: no project binding'; END IF;\n  IF EXISTS(SELECT FROM app.task_people WHERE workspace_id=ws AND task_id=task AND person_id=me)\n    AND NOT EXISTS(SELECT FROM app.identity_projects WHERE workspace_id=ws AND project_id=project AND owner_id=me)\n    AND NOT EXISTS(SELECT FROM app.identity_project_people WHERE workspace_id=ws AND project_id=project AND person_id=me)\n    THEN RAISE EXCEPTION 'denied: project access ended'; END IF;\n  INSERT INTO app.identity_project_people(workspace_id,project_id,person_id,access)\n    SELECT ws,project,me,CASE WHEN sec.role_of(me)='guest' THEN 'viewer' ELSE 'editor' END\n    WHERE NOT EXISTS(SELECT FROM app.identity_projects WHERE workspace_id=ws AND project_id=project AND owner_id=me)\n    ON CONFLICT(workspace_id,project_id,person_id) DO NOTHING;\n  INSERT INTO app.task_people(workspace_id,task_id,person_id) VALUES(ws,task,me) ON CONFLICT DO NOTHING;\n  PERFORM set_config('backbone.principal',old_person,true);\n  PERFORM gov._append('channel.thread_joined',p_thread::text,jsonb_build_object('person',me));\n  RETURN task;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true);RAISE;\nEND\n$$;\n\n-- gov/share_task.sql\n\n-- Share a task with the whole workspace: its requester, its beneficiary or an admin who sees it.\nCREATE OR REPLACE FUNCTION gov.share_task(p_task uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  me uuid := gov._person();\n  t record;\nBEGIN\n  SELECT * INTO t FROM app.tasks WHERE workspace_id = sec.current_workspace() AND id = p_task;\n  IF NOT FOUND OR NOT sec.task_visible(p_task) THEN\n    RAISE EXCEPTION 'not_found: no such task for this person';\n  END IF;\n  IF me NOT IN (t.requested_by, t.on_behalf_of) AND NOT sec.is_admin(me) THEN\n    RAISE EXCEPTION 'role: a task is shared by its people or an admin';\n  END IF;\n  IF NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=t.workspace_id AND task_id=p_task AND project_id=p_task) THEN RAISE EXCEPTION 'denied: use the project sharing boundary for a project task'; END IF;\n  INSERT INTO app.identity_workspace_projects(workspace_id,project_id) VALUES(t.workspace_id,p_task) ON CONFLICT DO NOTHING;\n  UPDATE app.tasks SET visibility = 'workspace' WHERE workspace_id = t.workspace_id AND id = p_task;\n  PERFORM gov._append('task.shared', p_task::text, '{}');\n  RETURN p_task;\nEND\n$$;\n\n-- gov/identity_directory_list.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE OR REPLACE FUNCTION gov.identity_directory_list(p_issuer text) RETURNS TABLE(id uuid, username text, external_id text, display_name text, active boolean, revision bigint)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  PERFORM gov._admin();\n  RETURN QUERY SELECT p.id,d.user_name,d.subject,d.display_name,p.status='active',d.revision\n  FROM app.identity_directory d JOIN app.principals p ON p.workspace_id=d.workspace_id AND p.id=d.principal_id\n  WHERE d.workspace_id=sec.current_workspace() AND d.issuer=p_issuer AND NOT EXISTS(SELECT FROM app.identity_directory_deleted x WHERE x.workspace_id=d.workspace_id AND x.principal_id=d.principal_id) ORDER BY p.id;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_directory_list(text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_directory_list(text) TO backbone_app;\n\n-- gov/identity_directory_delete.sql\n\n-- A directory deletion is terminal, issuer-scoped and atomic with access revocation.\nCREATE FUNCTION gov.identity_directory_delete(p_issuer text,p_person uuid,p_revision bigint) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE d record; ws uuid:=sec.current_workspace(); me uuid;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17)); PERFORM gov._lock_workspace(); me:=gov._admin();\n  SELECT * INTO d FROM app.identity_directory WHERE workspace_id=ws AND principal_id=p_person AND issuer=p_issuer FOR UPDATE;\n  IF NOT FOUND OR EXISTS(SELECT FROM app.identity_directory_deleted WHERE workspace_id=ws AND principal_id=p_person) THEN RETURN NULL; END IF;\n  IF d.revision<>p_revision THEN RAISE EXCEPTION 'stale: directory changed'; END IF;\n  PERFORM gov.identity_remove(p_person);\n  INSERT INTO app.identity_directory_deleted(workspace_id,principal_id) VALUES(ws,p_person);\n  PERFORM gov._append('identity.directory_deleted',p_person::text,jsonb_build_object('by',me));\n  RETURN p_person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_directory_delete(text,uuid,bigint) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_directory_delete(text,uuid,bigint) TO backbone_app;\n\nRESET ROLE;\n"} as const);
